<?php
declare(strict_types=1);
$isReceipt = !empty($isReceipt);
$order = is_array($orderDetail ?? null) ? $orderDetail : [];
$orderStatus = (string)($order['status'] ?? '');
$paymentStatus = (string)($order['payment_status'] ?? '');
$orderStatusLabel = match ($orderStatus) {'PAID'=>'Pagado','FULFILLED'=>'Entregado','CANCELLED'=>'Cancelado','PENDING_PAYMENT'=>'Pendiente de pago',default=>'Estado desconocido'};
$paymentStatusLabel = match ($paymentStatus) {'APPROVED'=>'Aprobado · simulación local','REJECTED'=>'Rechazado · simulación local','CANCELLED'=>'Cancelado · simulación local','PENDING'=>'Pendiente',default=>'Sin pago registrado'};
$items = is_array($order['items'] ?? null) ? $order['items'] : [];
$adminNextStatus = isAdmin() && $orderStatus==='PAID' && $paymentStatus==='APPROVED' ? 'FULFILLED' : (isAdmin() && $orderStatus==='PENDING_PAYMENT' && $paymentStatus!=='APPROVED' ? 'CANCELLED' : null);
?>
<section class="simple-page-head page-gutter order-head"><p class="eyebrow"><?= $isReceipt ? 'Comprobante de compra ficticia' : 'Detalle del pedido' ?> · VERDELIA</p><h1><?= $orderStatus === 'PAID' ? 'Gracias por tu<br><em>compra demo.</em>' : ($orderStatus === 'CANCELLED' ? 'Compra<br><em>cancelada.</em>' : 'Revisa tu<br><em>pedido.</em>') ?></h1><p>Pedido <strong><?= h($order['order_number'] ?? '') ?></strong> · <?= h($orderStatusLabel) ?></p></section>
<?php if (isset($flash['message']) && is_string($flash['message'])): ?><p class="auth-message <?= ($flash['type'] ?? '') === 'success' ? 'is-success' : 'is-error' ?> page-gutter" role="status"><?= h($flash['message']) ?></p><?php endif; ?>
<section class="receipt page-gutter" data-receipt>
  <header class="receipt-brand"><img src="/assets/images/brand/logo.svg" alt="VERDELIA" width="180" height="44"><div><strong>Demostración académica</strong><span>Pago local simulado · no representa un cobro real</span></div></header>
  <div class="receipt-meta"><div><span>Número de pedido</span><strong><?= h($order['order_number'] ?? '') ?></strong></div><div><span>Fecha</span><strong><?= h((string)($order['created_at'] ?? '')) ?></strong></div><div><span>Estado del pedido</span><strong><?= h($orderStatusLabel) ?></strong></div><div><span>Estado del pago</span><strong><?= h($paymentStatusLabel) ?></strong></div><div><span>Referencia simulada</span><strong><?= h($order['fake_reference'] ?? '—') ?></strong></div><div><span>Cliente</span><strong><?= h($order['delivery_name'] ?? $order['customer_name'] ?? '') ?> · <?= h($order['delivery_email'] ?? $order['customer_email'] ?? '') ?></strong></div><div class="receipt-address"><span>Entrega ficticia</span><strong><?= h($order['delivery_address'] ?? '') ?><?= !empty($order['delivery_phone']) ? ' · ' . h($order['delivery_phone']) : '' ?></strong><?php if (!empty($order['delivery_note'])): ?><small>Nota: <?= h($order['delivery_note']) ?></small><?php endif; ?></div></div>
  <div class="table-scroll receipt-table"><table><thead><tr><th>Producto</th><th>SKU</th><th>Cantidad</th><th>Precio</th><th>Importe</th></tr></thead><tbody>
    <?php foreach ($items as $item): ?><tr><td><?= h($item['name_snapshot']) ?></td><td><?= h($item['sku_snapshot']) ?></td><td><?= (int)$item['quantity'] ?></td><td><?= h(money((int)$item['unit_price_cents'])) ?></td><td><?= h(money((int)$item['line_total_cents'])) ?></td></tr><?php endforeach; ?>
  </tbody></table></div>
  <div class="receipt-totals"><div><span>Subtotal</span><strong><?= h(money((int)($order['subtotal_cents'] ?? 0))) ?></strong></div><div><span>Entrega demo</span><strong><?= (int)($order['shipping_cents'] ?? 0) === 0 ? 'Gratis' : h(money((int)$order['shipping_cents'])) ?></strong></div><div class="receipt-total"><span>Total</span><strong><?= h(money((int)($order['total_cents'] ?? 0))) ?></strong></div></div>
  <?php if (count($order['payment_attempts'] ?? []) > 1): ?><section class="payment-attempts"><h2>Intentos del simulador</h2><ul><?php foreach ($order['payment_attempts'] as $attempt): ?><li><?= h($attempt['created_at']) ?> · <?= h(match ($attempt['status']) {'APPROVED'=>'Aprobado','REJECTED'=>'Rechazado','CANCELLED'=>'Cancelado',default=>'Pendiente'}) ?> · <?= h($attempt['fake_reference']) ?></li><?php endforeach; ?></ul></section><?php endif; ?>
  <p class="receipt-note">Método: simulador local VERDELIA. No se recibió dinero ni se contactó a ninguna entidad financiera.</p>
  <div class="receipt-actions screen-only"><button class="button button-primary" type="button" data-print-receipt>Imprimir o guardar como PDF</button><?php if(isAdmin()): ?><a class="button button-outline" href="/admin/pedidos">Volver a pedidos</a><?php else: ?><a class="button button-outline" href="/cuenta/pedidos">Ver mis pedidos</a><?php endif; ?><?php if ($orderStatus === 'PENDING_PAYMENT' && !isAdmin()): ?><a class="button button-outline" href="/checkout">Reintentar simulación</a><?php endif; ?></div>
  <?php if(isAdmin() && $adminNextStatus!==null): ?><section class="admin-order-status screen-only"><h2>Gestión del pedido</h2><p><?= $orderStatus==='PAID'?'Solo se puede marcar como entregado un pedido con pago aprobado.':'Solo se pueden cancelar pedidos que aún no registran un pago aprobado.' ?> El inventario no se modifica desde este cambio de estado.</p><form method="post" action="/admin/pedidos/<?= rawurlencode((string)$order['order_number']) ?>/estado" onsubmit="return confirm('¿Confirmas este cambio de estado?');"><?= verdelia_csrf_field() ?><input type="hidden" name="status" value="<?= h($adminNextStatus) ?>"><label>Motivo *<input class="text-input" name="reason" maxlength="255" required placeholder="Motivo operativo"></label><button class="button button-primary" type="submit">Marcar <?= $adminNextStatus==='FULFILLED'?'como entregado':'como cancelado' ?></button></form></section><?php endif; ?>
  <?php if(isAdmin()): ?><section class="admin-order-status"><h2>Historial de estado</h2><?php if(($adminOrderHistory??[])===[]): ?><p>Aún no hay cambios administrativos de estado.</p><?php else: ?><ul><?php foreach($adminOrderHistory as $event): $from=match($event['from_status']){'PAID'=>'Pagado','FULFILLED'=>'Entregado','CANCELLED'=>'Cancelado',default=>'Pendiente de pago'};$to=match($event['to_status']){'PAID'=>'Pagado','FULFILLED'=>'Entregado','CANCELLED'=>'Cancelado',default=>'Pendiente de pago'}; ?><li><?= h($event['changed_at']) ?> · <?= h($from) ?> → <?= h($to) ?> · <?= h($event['admin_name']) ?> · <?= h($event['reason']) ?></li><?php endforeach; ?></ul><?php endif; ?></section><?php endif; ?>
</section>
